"""Incident inputs; IDs, lifecycle state and dates are generated by the system."""

from common.errors import ValidationError
from common.validators import choice, clean_text, parse_id

SEVERITIES = ("Low", "Medium", "High", "Critical")
STATUSES = ("Open", "Under Investigation", "Mitigated", "Resolved", "Closed")
NEXT_STATUS = dict(zip(STATUSES, STATUSES[1:]))
MAX_ID = 9223372036854775807


def incident_id(value, field="incident id"):
    """Accept positive integer IDs without overflowing SQLite or Python parsing."""
    if type(value) is int:
        if 1 <= value <= MAX_ID:
            return value
        raise ValidationError(f"{field} must be a positive integer within SQLite's range")
    if isinstance(value, str) and value.isascii() and value.isdigit():
        value = value.lstrip("0") or "0"
        if len(value) > 19:
            raise ValidationError(f"{field} is outside the supported integer range")
    number = parse_id(value, field)
    if number > MAX_ID:
        raise ValidationError(f"{field} is outside the supported integer range")
    return number


def related_id(value, field):
    """JSON relationships must be integer IDs, rather than booleans or strings."""
    if type(value) is not int:
        raise ValidationError(f"{field} must be a positive integer")
    return incident_id(value, field)


class Incident:
    """Validate the six required incident creation fields."""

    def __init__(self, title, description, category, severity_level, reporter_id, asset_id):
        self.title = clean_text(title, "title", max_length=255)
        self.description = clean_text(description, "description", max_length=4000)
        self.category = clean_text(category, "category", max_length=100)
        self.severity_level = choice(severity_level, "severity_level", SEVERITIES)
        self.reporter_id = related_id(reporter_id, "reporter_id")
        self.asset_id = related_id(asset_id, "asset_id")


def investigation_note(value):
    return clean_text(value, "note_content", max_length=4000)
